1	// IMAP engine for the native webmail client.
2	//
3	// Plain server-side module (NOT "use server"): it holds the short-lived imapflow
4	// connection helpers, special-use → role mapping, and the mailbox-ownership
5	// resolver shared by the server actions (lib/actions-mail.ts) and the attachment
6	// download route (app/api/mail/attachment/route.ts). Every connection is opened
7	// per-request and always closed. It is never imported into a client bundle.
8	
9	import { ImapFlow } from "imapflow";
10	import type {
11	  FetchMessageObject,
12	  MailboxLockOptions,
13	  MessageAddressObject,
14	  MessageStructureObject,
15	} from "imapflow";
16	import { requireUser } from "@/lib/auth";
17	import { db } from "@/lib/db";
18	import { decryptSecret } from "@/lib/crypto-box";
19	import { MAIL_IMAP_HOST, MAIL_IMAP_PORT, type MailAddress, type MailFolderRole } from "./types";
20	import type { User } from "@prisma/client";
21	
22	// mailparser ships no bundled type declarations and its untyped JS module can't
23	// be augmented via `declare module`. Instead we describe the slice we use with
24	// local interfaces and import `simpleParser` with a suppressed-error import,
25	// exposing a single typed `parseMessage` wrapper for the rest of the backend.
26	// @ts-ignore -- mailparser has no type declarations
27	import { simpleParser as _simpleParser } from "mailparser";
28	
29	export interface ParsedAttachment {
30	  type?: string;
31	  partId?: string;
32	  filename?: string;
33	  contentType?: string;
34	  contentDisposition?: string;
35	  size?: number;
36	  content?: Buffer;
37	  cid?: string;
38	  contentId?: string;
39	  related?: boolean;
40	}
41	export interface ParsedMessage {
42	  subject?: string;
43	  from?: { value?: { name?: string; address?: string }[]; text?: string };
44	  to?: unknown;
45	  cc?: unknown;
46	  bcc?: unknown;
47	  date?: Date;
48	  messageId?: string;
49	  inReplyTo?: string;
50	  references?: string | string[];
51	  html?: string | false;
52	  text?: string;
53	  textAsHtml?: string;
54	  attachments: ParsedAttachment[];
55	}
56	
57	const simpleParser = _simpleParser as (
58	  source: Buffer | string,
59	  options?: Record<string, unknown>,
60	) => Promise<ParsedMessage>;
61	
62	/** Parse a raw RFC822 message source into a typed structure (via mailparser). */
63	export async function parseMessage(source: Buffer | string): Promise<ParsedMessage> {
64	  return simpleParser(source);
65	}
66	
67	/** The TLS servername the mail server's certificate is issued for. */
68	export const MAIL_TLS_SERVERNAME = process.env.MAIL_TLS_SERVERNAME || "mail.nxeon.cloud";
69	
70	/** Minimal credential shape needed to authenticate an IMAP/SMTP session. */
71	export type MailboxCredentials = { address: string; password: string };
72	
73	/** A user mailbox row plus the decrypted credential, resolved + ownership-checked. */
74	export type ResolvedMailbox = {
75	  user: User;
76	  mailboxId: string;
77	  address: string;
78	  quotaMB: number | null;
79	  cred: MailboxCredentials;
80	};
81	
82	/**
83	 * Resolve the mailbox a request may act on. Requires an authenticated user,
84	 * loads only mailboxes belonging to that user's email subscriptions, and (when
85	 * `mailboxAddress` is given) verifies it is one of them. Decrypts the stored
86	 * credential; throws a friendly error if the password was never captured.
87	 *
88	 * NEVER returns a mailbox the caller does not own.
89	 */
90	export async function resolveMailbox(mailboxAddress?: string): Promise<ResolvedMailbox> {
91	  const user = await requireUser();
92	  const boxes = await db.mailbox.findMany({
93	    where: { subscription: { userId: user.id } },
94	    include: { subscription: true },
95	    orderBy: { createdAt: "asc" },
96	  });
97	  if (boxes.length === 0) {
98	    throw new Error("You do not have a mailbox yet. Add an email plan to use webmail.");
99	  }
100	
101	  let box = boxes[0];
102	  if (mailboxAddress) {
103	    const wanted = mailboxAddress.trim().toLowerCase();
104	    const match = boxes.find((b) => b.address.toLowerCase() === wanted);
105	    if (!match) throw new Error("You do not have access to that mailbox.");
106	    box = match;
107	  }
108	
109	  const password = decryptSecret(box.passwordEnc);
110	  if (!password) {
111	    throw new Error("Please reset your mailbox password first to enable webmail access.");
112	  }
113	
114	  return {
115	    user,
116	    mailboxId: box.id,
117	    address: box.address,
118	    quotaMB: box.quotaMB ?? null,
119	    cred: { address: box.address, password },
120	  };
121	}
122	
123	/** Build a per-request imapflow client for the given credential. */
124	export function createImapClient(cred: MailboxCredentials): ImapFlow {
125	  return new ImapFlow({
126	    host: MAIL_IMAP_HOST,
127	    port: MAIL_IMAP_PORT,
128	    secure: true,
129	    // We connect by internal IP but the cert is for mail.nxeon.cloud — set SNI
130	    // and validation servername so TLS verifies against the right name.
131	    servername: MAIL_TLS_SERVERNAME,
132	    tls: { servername: MAIL_TLS_SERVERNAME, rejectUnauthorized: false },
133	    auth: { user: cred.address, pass: cred.password },
134	    logger: false,
135	    disableAutoIdle: true,
136	  });
137	}
138	
139	/**
140	 * Open a short-lived IMAP connection, run `fn`, and ALWAYS close it (graceful
141	 * logout, falling back to a hard close). Suitable for one operation per request.
142	 */
143	export async function withImap<T>(cred: MailboxCredentials, fn: (client: ImapFlow) => Promise<T>): Promise<T> {
144	  const client = createImapClient(cred);
145	  await client.connect();
146	  try {
147	    return await fn(client);
148	  } finally {
149	    try {
150	      await client.logout();
151	    } catch {
152	      try {
153	        client.close();
154	      } catch {
155	        /* already gone */
156	      }
157	    }
158	  }
159	}
160	
161	/**
162	 * Like `withImap` but also selects `path` under a mailbox lock (released before
163	 * the connection closes). Use for any op that fetches/searches/mutates messages.
164	 */
165	export async function withMailbox<T>(
166	  cred: MailboxCredentials,
167	  path: string,
168	  fn: (client: ImapFlow) => Promise<T>,
169	  opts?: { readOnly?: boolean },
170	): Promise<T> {
171	  return withImap(cred, async (client) => {
172	    const lockOpts: MailboxLockOptions = { readOnly: opts?.readOnly };
173	    const lock = await client.getMailboxLock(path, lockOpts);
174	    try {
175	      return await fn(client);
176	    } finally {
177	      lock.release();
178	    }
179	  });
180	}
181	
182	/** Map an IMAP special-use flag / folder name to our MailFolderRole. */
183	export function folderRole(path: string, specialUse?: string): MailFolderRole {
184	  const su = (specialUse || "").toLowerCase();
185	  if (su === "\\inbox" || path.toUpperCase() === "INBOX") return "inbox";
186	  switch (su) {
187	    case "\\sent":
188	      return "sent";
189	    case "\\drafts":
190	      return "drafts";
191	    case "\\trash":
192	      return "trash";
193	    case "\\junk":
194	      return "junk";
195	    case "\\archive":
196	    case "\\all":
197	      return "archive";
198	  }
199	  // Fall back to common folder names for servers that don't advertise SPECIAL-USE.
200	  const leaf = (path.split(/[/.]/).pop() || path).toLowerCase();
201	  if (leaf === "inbox") return "inbox";
202	  if (["sent", "sent items", "sent mail", "sent messages"].includes(leaf)) return "sent";
203	  if (["drafts", "draft"].includes(leaf)) return "drafts";
204	  if (["trash", "deleted", "deleted items", "deleted messages", "bin"].includes(leaf)) return "trash";
205	  if (["junk", "spam", "junk email", "junk e-mail"].includes(leaf)) return "junk";
206	  if (["archive", "archives", "all mail", "all"].includes(leaf)) return "archive";
207	  return "custom";
208	}
209	
210	/** Convert an imapflow envelope address to our MailAddress shape. */
211	export function toMailAddress(a: MessageAddressObject | undefined): MailAddress {
212	  return { name: a?.name || undefined, address: a?.address || "" };
213	}
214	
215	/** Convert an array of imapflow envelope addresses to MailAddress[]. */
216	export function toMailAddresses(list: MessageAddressObject[] | undefined): MailAddress[] {
217	  return (list || []).map(toMailAddress).filter((a) => a.address);
218	}
219	
220	/**
221	 * Walk a BODYSTRUCTURE tree and return the IMAP part id of the best text part
222	 * to preview: prefers text/plain, then text/html, then the first leaf. Returns
223	 * "1" for a simple single-part message (whose structure carries no part id).
224	 */
225	export function findPreviewPart(structure: MessageStructureObject | undefined): { part: string; isHtml: boolean } {
226	  if (!structure) return { part: "1", isHtml: false };
227	  const leaves: MessageStructureObject[] = [];
228	  const walk = (node: MessageStructureObject) => {
229	    if (node.childNodes && node.childNodes.length) {
230	      node.childNodes.forEach(walk);
231	    } else {
232	      leaves.push(node);
233	    }
234	  };
235	  walk(structure);
236	
237	  const isBody = (n: MessageStructureObject) => (n.disposition || "").toLowerCase() !== "attachment";
238	  const plain = leaves.find((n) => (n.type || "").toLowerCase() === "text/plain" && isBody(n));
239	  if (plain) return { part: plain.part || "1", isHtml: false };
240	  const html = leaves.find((n) => (n.type || "").toLowerCase() === "text/html" && isBody(n));
241	  if (html) return { part: html.part || "1", isHtml: true };
242	  return { part: leaves[0]?.part || "1", isHtml: (leaves[0]?.type || "").toLowerCase() === "text/html" };
243	}
244	
245	/** True if a BODYSTRUCTURE tree contains at least one attachment-like part. */
246	export function structureHasAttachments(structure: MessageStructureObject | undefined): boolean {
247	  if (!structure) return false;
248	  let found = false;
249	  const walk = (node: MessageStructureObject) => {
250	    const type = (node.type || "").toLowerCase();
251	    const disp = (node.disposition || "").toLowerCase();
252	    if (node.childNodes && node.childNodes.length) {
253	      node.childNodes.forEach(walk);
254	      return;
255	    }
256	    if (disp === "attachment") found = true;
257	    else if (!type.startsWith("text/") && !type.startsWith("multipart/")) found = true;
258	  };
259	  walk(structure);
260	  return found;
261	}
262	
263	/** Read imapflow message flags into the summary booleans. */
264	export function readFlags(flags: Set<string> | undefined): { seen: boolean; flagged: boolean; answered: boolean } {
265	  const f = flags ?? new Set<string>();
266	  return { seen: f.has("\\Seen"), flagged: f.has("\\Flagged"), answered: f.has("\\Answered") };
267	}
268	
269	/** Best-effort ISO date string from an imapflow fetch result. */
270	export function isoDate(msg: Pick<FetchMessageObject, "envelope" | "internalDate">): string {
271	  const d = msg.envelope?.date || (msg.internalDate ? new Date(msg.internalDate) : undefined);
272	  const date = d instanceof Date ? d : d ? new Date(d) : new Date(0);
273	  return Number.isNaN(date.getTime()) ? new Date(0).toISOString() : date.toISOString();
274	}
