114	// ---------- Mutations ----------
115	
116	/** Create a mail domain (idempotent-ish: if it already exists Mailcow errors,
117	 * which callers may ignore). */
118	export async function mcCreateDomain(domain: string): Promise<unknown> {
119	  return mcRequest("POST", "/add/domain", {
120	    domain,
121	    description: `nxeon ${domain}`,
122	    aliases: 400,
123	    mailboxes: 100,
124	    defquota: 1024,
125	    maxquota: 102400,
126	    quota: 102400,
127	    active: "1",
128	    restart_sogo: "0",
129	  });
130	}
131	
132	/** True if the domain already exists in Mailcow. */
133	export async function mcDomainExists(domain: string): Promise<boolean> {
134	  try {
135	    const res = await mcRequest("GET", `/get/domain/${encodeURIComponent(domain)}`);
136	    // Mailcow returns {} (or []) for an unknown domain, or the domain object.
137	    if (!res) return false;
138	    if (Array.isArray(res)) return res.length > 0;
139	    if (typeof res === "object") {
140	      return "domain_name" in res || "domain" in res;
141	    }
142	    return false;
143	  } catch {
144	    return false;
145	  }
146	}
