166	/** Activate / deactivate a mailbox (used for suspend/resume). */
167	export async function mcSetMailboxActive(address: string, active: boolean): Promise<unknown> {
168	  return mcRequest("POST", "/edit/mailbox", {
169	    items: [address],
170	    attr: { active: active ? "1" : "0" },
