186	/** Change a mailbox quota (MB). */
187	export async function mcSetQuota(address: string, quotaMB: number): Promise<unknown> {
188	  return mcRequest("POST", "/edit/mailbox", {
189	    items: [address],
190	    attr: { quota: quotaMB },
191	  });
