101	/** List the mailbox's folders with unread/total counts and their role. */
102	export async function listFolders(mailboxAddress?: string): Promise<MailFolder[]> {
103	  const { cred } = await resolveMailbox(mailboxAddress);
104	  return withImap(cred, async (client) => {
105	    const list = await client.list({ statusQuery: { messages: true, unseen: true } });
106	    const folders: MailFolder[] = [];
107	    for (const f of list) {
108	      // Skip containers that can't hold messages.
109	      if (f.flags?.has("\\Noselect")) continue;
110	      folders.push({
111	        path: f.path,
112	        name: f.name || f.path,
113	        role: folderRole(f.path, f.specialUse),
114	        unread: f.status?.unseen ?? 0,
115	        total: f.status?.messages ?? 0,
116	      });
117	    }
118	    // Stable, useful ordering: known roles first, then custom alphabetically.
119	    const order: Record<string, number> = { inbox: 0, sent: 1, drafts: 2, archive: 3, junk: 4, trash: 5, custom: 6 };
120	    folders.sort((a, b) => (order[a.role] - order[b.role]) || a.name.localeCompare(b.name));
121	    return folders;
122	  });
123	}
