129	/** Decode a downloaded body part (transfer-encoding already decoded by server). */
130	function decodeCharset(buf: Buffer, charset?: string): string {
131	  const cs = (charset || "").toLowerCase();
132	  if (/latin1|8859|1252/.test(cs)) return buf.toString("latin1");
133	  return buf.toString("utf8");
134	}
