136	/** Fetch a short, transfer-decoded snippet of a message's text part for preview. */
137	async function fetchPreview(client: ImapFlow, uid: number, part: string): Promise<string> {
138	  try {
139	    const { meta, content } = await client.download(String(uid), part, { uid: true, maxBytes: 4096 });
140	    const chunks: Buffer[] = [];
141	    for await (const chunk of content) chunks.push(chunk as Buffer);
142	    return previewText(decodeCharset(Buffer.concat(chunks), meta.charset));
143	  } catch {
144	    return "";
145	  }
146	}
