228	/** Fetch one full message: parsed + SANITISED html, attachments listed, marked \Seen. */
229	export async function getMessage(folder: string, uid: number, mailboxAddress?: string): Promise<MessageFull> {
230	  const { cred } = await resolveMailbox(mailboxAddress);
231	
232	  return withMailbox(cred, folder, async (client) => {
233	    const msg = await client.fetchOne(
234	      String(uid),
235	      { uid: true, source: true, flags: true, envelope: true, internalDate: true },
236	      { uid: true },
237	    );
238	    if (!msg || !msg.source) throw new Error("Message not found.");
239	
240	    const parsed = await parseMessage(msg.source);
241	    const flags = readFlags(msg.flags);
242	    const env = msg.envelope;
243	
244	    const attachments = (parsed.attachments || [])
245	      .filter((a) => a.related !== true) // skip inline/embedded (cid) images
246	      .map((a, i) => ({
247	        id: `${uid}:${a.partId ?? String(i + 1)}`,
248	        filename: a.filename || `attachment-${i + 1}`,
249	        mime: a.contentType || "application/octet-stream",
250	        sizeBytes: a.size ?? 0,
251	      }));
252	
253	    const full: MessageFull = {
254	      uid,
255	      folder,
256	      from: toMailAddress(env?.from?.[0]),
257	      to: toMailAddresses(env?.to),
258	      cc: toMailAddresses(env?.cc),
259	      subject: env?.subject || parsed.subject || "(no subject)",
260	      preview: previewText(parsed.text || (typeof parsed.html === "string" ? parsed.html : "")),
261	      date: isoDate(msg),
262	      seen: true, // becomes read as a side effect of opening
263	      flagged: flags.flagged,
264	      answered: flags.answered,
265	      hasAttachments: attachments.length > 0,
266	      html: typeof parsed.html === "string" ? safeHtml(parsed.html) : null,
267	      text: parsed.text ?? null,
268	      attachments,
269	    };
270	
271	    // Mark read (mailbox opened read-write). Best effort — never fail the read.
272	    try {
273	      await client.messageFlagsAdd(String(uid), ["\\Seen"], { uid: true });
274	    } catch {
275	      /* ignore */
276	    }
277	
278	    return full;
279	  });
280	}
