286	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
287	
288	/** Parse a comma/semicolon-separated recipient string into validated addresses. */
289	function parseRecipients(input: string | undefined): { list: string[]; invalid: string[] } {
290	  const parts = (input || "")
291	    .split(/[,;]+/)
292	    .map((s) => s.trim())
293	    .filter(Boolean);
294	  const list: string[] = [];
295	  const invalid: string[] = [];
296	  for (const p of parts) {
297	    // Tolerate "Name <addr>" form by extracting the address.
298	    const m = p.match(/<([^>]+)>/);
299	    const addr = (m ? m[1] : p).trim();
300	    if (EMAIL_RE.test(addr)) list.push(addr);
301	    else invalid.push(p);
302	  }
303	  return { list, invalid };
304	}
