378	/**
379	 * Send a message from the user's own mailbox over SMTP submission, append a copy
380	 * to Sent, and (for replies) thread it + flag the original \Answered.
381	 */
382	export async function sendMessage(
383	  payload: SendPayload,
384	  mailboxAddress?: string,
385	): Promise<{ ok: boolean; error?: string }> {
386	  const { user, cred } = await resolveMailbox(mailboxAddress);
387	  enforceRateLimit(`mail:send:burst:${user.id}`, { max: 5, windowMs: 60 * 1000 });
388	  enforceRateLimit(`mail:send:${user.id}`, { max: 60, windowMs: 60 * 60 * 1000 });
389	
390	  const to = parseRecipients(payload.to);
391	  const cc = parseRecipients(payload.cc);
392	  const bcc = parseRecipients(payload.bcc);
393	  const invalid = [...to.invalid, ...cc.invalid, ...bcc.invalid];
394	  if (invalid.length) return { ok: false, error: `Invalid recipient(s): ${invalid.join(", ")}` };
395	  if (to.list.length === 0) return { ok: false, error: "Add at least one recipient." };
396	  if (!payload.subject?.trim() && !payload.text?.trim() && !payload.html?.trim()) {
397	    return { ok: false, error: "Nothing to send — add a subject or a message." };
398	  }
399	
400	  const decoded = decodeAttachments(payload.attachments);
401	  if (!decoded.ok) return { ok: false, error: decoded.error };
402	  const attachments = decoded.attachments;
403	
404	  try {
405	    // Look up threading headers when this is a reply.
406	    let inReplyTo: string | undefined;
407	    let references: string | undefined;
408	    if (payload.inReplyToUid && payload.replyFolder) {
409	      try {
410	        await withMailbox(cred, payload.replyFolder, async (client) => {
411	          const orig = await client.fetchOne(String(payload.inReplyToUid), { uid: true, envelope: true }, { uid: true });
412	          if (orig && orig.envelope?.messageId) {
413	            inReplyTo = orig.envelope.messageId;
414	            references = orig.envelope.messageId;
415	          }
416	          // Mark the message we're replying to as answered (best effort).
417	          try {
418	            await client.messageFlagsAdd(String(payload.inReplyToUid), ["\\Answered"], { uid: true });
419	          } catch {
420	            /* ignore */
421	          }
422	        });
423	      } catch {
424	        /* original not found — send without threading headers */
425	      }
426	    }
427	
428	    // Compile the message once so the exact bytes are both sent and saved to Sent.
429	    const composer = nodemailer.createTransport({ streamTransport: true, buffer: true, newline: "\r\n" });
430	    const built = await composer.sendMail({
431	      from: cred.address,
432	      to: to.list,
433	      cc: cc.list.length ? cc.list : undefined,
434	      bcc: bcc.list.length ? bcc.list : undefined,
435	      subject: payload.subject || "",
436	      text: payload.text || undefined,
437	      html: payload.html || undefined,
438	      attachments: attachments.length ? attachments : undefined,
439	      inReplyTo,
440	      references,
441	    });
442	    const raw = built.message as Buffer;
443	
444	    const smtp = nodemailer.createTransport({
445	      host: MAIL_SMTP_HOST,
446	      port: MAIL_SMTP_PORT,
447	      secure: MAIL_SMTP_PORT === 465,
448	      requireTLS: MAIL_SMTP_PORT !== 465,
449	      tls: { servername: MAIL_TLS_SERVERNAME, rejectUnauthorized: false },
450	      auth: { user: cred.address, pass: cred.password },
451	    });
452	    await smtp.sendMail({ envelope: built.envelope, raw });
453	
454	    // Save a copy to Sent (best effort — the message already went out).
455	    try {
456	      await withImap(cred, async (client) => {
457	        const sentPath = await findSentPath(client);
458	        await client.append(sentPath, raw, ["\\Seen"]);
459	      });
460	    } catch {
461	      /* Sent append failed — not fatal */
462	    }
463	
464	    return { ok: true };
465	  } catch (e) {
466	    return { ok: false, error: String((e as Error)?.message ?? e).slice(0, 300) };
467	  }
468	}
