57	function domainOf(address: string): string {
58	  const at = address.lastIndexOf("@");
59	  return at >= 0 ? address.slice(at + 1).toLowerCase() : "";
60	}
61	
62	/** Format a stored Date as a `YYYY-MM-DD` string (or "" when null). */
63	function toDateInput(d: Date | null | undefined): string {
64	  if (!d) return "";
65	  try {
66	    return d.toISOString().slice(0, 10);
67	  } catch {
68	    return "";
69	  }
70	}
71	
72	/** Parse a `YYYY-MM-DD` string into a UTC Date, or null when blank/invalid. */
73	function fromDateInput(s: string | null | undefined): Date | null {
74	  const v = (s ?? "").trim();
75	  if (!v) return null;
76	  const d = new Date(`${v}T00:00:00.000Z`);
77	  return Number.isNaN(d.getTime()) ? null : d;
78	}
