80	/** Rate-limit gate returning a friendly `{ ok:false }` instead of throwing. */
81	function gate(key: string, max: number, windowMs: number): Result | null {
82	  const r = checkRateLimit(key, { max, windowMs });
83	  if (!r.ok) return { ok: false, error: `Too many requests — wait ${r.retryAfterSec}s and try again.` };
84	  return null;
85	}
