127	/**
128	 * Save identity + signature onto the mailbox row. Only the fields actually
129	 * present in `input` are written, so the Identity and Signature sub-forms can
130	 * each save independently without clobbering the other's data.
131	 *
132	 * Signature HTML is sanitised server-side with `safeHtml` (defence in depth —
133	 * the client sanitises too) and a plain-text version is derived into the legacy
134	 * `signature` column so the text/plain MIME part always has a fallback.
135	 */
136	export async function saveMailboxSettings(
137	  input: {
138	    displayName?: string;
139	    replyTo?: string;
140	    organization?: string;
141	    signatureHtml?: string;
142	    signatureEnabled?: boolean;
143	    signatureOnReply?: boolean;
144	    signaturePlacement?: string;
145	  },
146	  mailboxAddress?: string,
147	): Promise<Result> {
148	  const { user, mailboxId } = await resolveMailbox(mailboxAddress);
149	  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
150	  if (limited) return limited;
151	
152	  const data: {
153	    displayName?: string | null;
154	    replyTo?: string | null;
155	    organization?: string | null;
156	    signatureHtml?: string | null;
157	    signature?: string | null;
158	    signatureEnabled?: boolean;
159	    signatureOnReply?: boolean;
160	    signaturePlacement?: string;
161	  } = {};
162	
163	  if (input.displayName !== undefined) {
164	    const displayName = input.displayName.trim();
165	    if (displayName.length > 120) return { ok: false, error: "Display name is too long (max 120 characters)." };
166	    data.displayName = displayName || null;
167	  }
168	
169	  if (input.replyTo !== undefined) {
170	    const replyTo = input.replyTo.trim();
171	    if (replyTo && !EMAIL_RE.test(replyTo)) return { ok: false, error: "Reply-to must be a valid email address." };
172	    data.replyTo = replyTo || null;
173	  }
174	
175	  if (input.organization !== undefined) {
176	    const organization = input.organization.trim();
177	    if (organization.length > 200) return { ok: false, error: "Organization is too long (max 200 characters)." };
178	    data.organization = organization || null;
179	  }
180	
181	  if (input.signatureHtml !== undefined) {
182	    const clean = safeHtml(input.signatureHtml);
183	    if (clean.length > SIGNATURE_HTML_MAX) {
184	      return { ok: false, error: "Signature is too long. Please shorten it." };
185	    }
186	    data.signatureHtml = clean || null;
187	    const plain = signatureHtmlToText(clean);
188	    data.signature = plain ? plain : null;
189	  }
190	
191	  if (input.signatureEnabled !== undefined) data.signatureEnabled = Boolean(input.signatureEnabled);
192	  if (input.signatureOnReply !== undefined) data.signatureOnReply = Boolean(input.signatureOnReply);
193	  if (input.signaturePlacement !== undefined) {
194	    data.signaturePlacement = input.signaturePlacement === "above" ? "above" : "below";
195	  }
196	
197	  if (Object.keys(data).length > 0) {
198	    await db.mailbox.update({ where: { id: mailboxId }, data });
199	  }
200	  return { ok: true };
201	}
