203	/**
204	 * Store a "forward a copy" rule on the mailbox row.
205	 *
206	 * NOTE: this is STORE-ONLY and honestly labelled as such in the UI. Mailcow has
207	 * no safe, mailbox-scoped forwarding primitive we can drive from the customer
208	 * panel without risking the account's real mail routing (an alias whose address
209	 * equals an existing mailbox is rejected by Mailcow, and editing SOGo sieve
210	 * filters is out of API scope), so we persist the preference and surface a
211	 * clear "stored, not yet auto-forwarding" note rather than pretend it forwards.
212	 */
213	export async function saveForwarding(
214	  input: { enabled: boolean; address?: string; keepCopy?: boolean },
215	  mailboxAddress?: string,
216	): Promise<Result> {
217	  const { user, mailboxId, address } = await resolveMailbox(mailboxAddress);
218	  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
219	  if (limited) return limited;
220	
221	  const enabled = Boolean(input.enabled);
222	  const target = (input.address ?? "").trim().toLowerCase();
223	  const keepCopy = input.keepCopy !== false;
224	
225	  if (enabled) {
226	    if (!target) return { ok: false, error: "Enter an address to forward to." };
227	    if (!EMAIL_RE.test(target)) return { ok: false, error: "That doesn't look like a valid email address." };
228	    if (target === address.toLowerCase()) return { ok: false, error: "Forwarding to this mailbox itself does nothing." };
229	  }
230	
231	  await db.mailbox.update({
232	    where: { id: mailboxId },
233	    data: {
234	      forwardingAddress: enabled && target ? target : null,
235	      forwardKeepCopy: keepCopy,
236	    },
237	  });
238	  return { ok: true };
239	}
