241	/**
242	 * Save the auto-reply / vacation responder onto the mailbox row.
243	 *
244	 * NOTE: this is STORE-ONLY. Mailcow's REST API exposes no reliable
245	 * vacation/auto-responder endpoint (auto-replies live in SOGo user preferences,
246	 * not the admin API), so we persist the settings and the UI labels them as
247	 * "saved; server-side delivery is rolling out". We do NOT pretend the mail
248	 * server sends them.
249	 */
250	export async function saveAutoReply(
251	  input: { enabled: boolean; subject?: string; body?: string; start?: string | null; end?: string | null },
252	  mailboxAddress?: string,
253	): Promise<Result> {
254	  const { user, mailboxId } = await resolveMailbox(mailboxAddress);
255	  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
256	  if (limited) return limited;
257	
258	  const enabled = Boolean(input.enabled);
259	  const subject = (input.subject ?? "").trim();
260	  const body = (input.body ?? "").trim();
261	  if (subject.length > 200) return { ok: false, error: "Subject is too long (max 200 characters)." };
262	  if (body.length > 5000) return { ok: false, error: "Message is too long (max 5000 characters)." };
263	  if (enabled && !body) return { ok: false, error: "Add an auto-reply message before turning it on." };
264	
265	  const start = fromDateInput(input.start);
266	  const end = fromDateInput(input.end);
267	  if (start && end && start.getTime() > end.getTime()) {
268	    return { ok: false, error: "The start date must be on or before the end date." };
269	  }
270	
271	  await db.mailbox.update({
272	    where: { id: mailboxId },
273	    data: {
274	      autoReplyEnabled: enabled,
275	      autoReplySubject: subject || null,
276	      autoReplyBody: body || null,
277	      autoReplyStart: start,
278	      autoReplyEnd: end,
279	    },
280	  });
281	  return { ok: true };
282	}
