53	/**
54	 * Business Email — mailbox hosting per registered domain.
55	 *
56	 * An `EmailPlan` is a pricing tier (N mailboxes, GB/mailbox, price, term). A
57	 * customer subscribes one of their own domains to a tier (`EmailSubscription`),
58	 * which debits the wallet, then manages individual `Mailbox` rows under it.
59	 *
60	 * Mail delivery runs through a self-hosted Mailcow server, reached via lib/mailcow.ts
61	 * (config from MAILCOW_API_URL / MAILCOW_API_KEY). Creating a Mailbox row records
62	 * intent (status PROVISIONING); we then attempt to provision the real mailbox on
63	 * Mailcow and flip the row to ACTIVE, or FAILED if the call errors. All Mailcow
64	 * calls are additive and failure-tolerant — a Mailcow outage never breaks the
65	 * order flow; the row persists and can be retried via retryMailboxProvision.
66	 *
67	 * This module owns:
68	 *   - orderEmailHosting (customer subscribe)
69	 *   - addMailbox / removeMailbox / retryMailboxProvision (customer mailbox management)
70	 *   - adminSaveEmailPlan / adminToggleEmailPlan / adminDeleteEmailPlan (CRUD)
71	 */
72	
73	type Result = { error?: string; ok?: boolean };
74	
75	/**
76	 * Provision (or re-provision) a mailbox on Mailcow. Never throws — records the
77	 * outcome on the Mailbox row (status ACTIVE on success, FAILED on error) and
78	 * returns it. When Mailcow isn't configured the row is left PROVISIONING so it
79	 * can be picked up once the integration is wired.
80	 */
81	async function provisionMailboxOnMailcow(mailbox: {
82	  id: string;
83	  address: string;
84	  quotaMB: number | null;
85	  subscription: { domainName: string };
86	}): Promise<"ACTIVE" | "FAILED" | "PROVISIONING"> {
87	  if (!mailcowConfigured()) return "PROVISIONING";
88	
89	  const [localPart] = mailbox.address.split("@");
90	  const domain = mailbox.subscription.domainName;
91	  const quotaMB = mailbox.quotaMB ?? 1024;
92	
93	  try {
94	    // Ensure the mail domain exists before adding the mailbox.
95	    if (!(await mcDomainExists(domain))) {
96	      // A concurrent create or pre-existing domain can still error here; ignore
97	      // and let the mailbox add be the real signal.
98	      await mcCreateDomain(domain).catch(() => {});
99	    }
100	
101	    const password = randomBytes(18).toString("base64url");
102	    await mcCreateMailbox({
103	      localPart,
104	      domain,
105	      name: mailbox.address,
106	      password,
107	      quotaMB,
108	    });
109	
110	    await db.mailbox.update({
111	      where: { id: mailbox.id },
112	      data: { status: "ACTIVE", passwordEnc: encryptSecret(password) },
113	    });
114	    return "ACTIVE";
115	  } catch (e) {
116	    await db.mailbox
117	      .update({ where: { id: mailbox.id }, data: { status: "FAILED" } })
118	      .catch(() => {});
119	    console.warn(`[mailcow] provisioning ${mailbox.address} failed:`, e);
120	    return "FAILED";
121	  }
122	}
