222	/**
223	 * Subscribe one of the caller's registered domains to an email plan. Validates
224	 * domain ownership + plan availability, then atomically debits the wallet and
225	 * creates the EmailSubscription with an expiry set from the plan term.
226	 *
227	 * The subscription is created ACTIVE (billing-wise), but no mailboxes are
228	 * provisioned with a mail provider yet — that integration is pending, and the
229	 * UI surfaces every mailbox as "provisioning" until it lands.
230	 */
231	export async function orderEmailHosting(
232	  domainName: string,
233	  emailPlanId: string,
234	): Promise<Result> {
235	  const user = await requireUser();
236	
237	  const name = String(domainName ?? "")
238	    .trim()
239	    .toLowerCase()
240	    .replace(/\.$/, "");
241	  if (!name) return { error: "Enter a domain." };
242	  if (!domainRe.test(name)) return { error: "Enter a valid domain (e.g. example.com)." };
243	
244	  // Is the domain registered inside Nxeon? If so we control its DNS and can
245	  // treat mail as pre-verifiable; otherwise it's an EXTERNAL domain that must be
246	  // verified via DNS before mail flows.
247	  const inAccount = await db.domain.findFirst({ where: { name, userId: user.id } });
248	  const external = !inAccount;
249	
250	  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
251	  if (!plan || !plan.active) return { error: "That email plan isn't available." };
252	
253	  // One subscription per domain — ACROSS ALL ACCOUNTS, not just this one.
254	  //
255	  // SECURITY (fixed 2026-07-25): this lookup was scoped to `userId: user.id`,
256	  // which let anyone buy a subscription for a domain another customer already
257	  // held. That was a cross-tenant email takeover: `addMailbox` only checks that
258	  // the SUBSCRIPTION belongs to the caller, and Mailcow keys mailboxes by
259	  // ADDRESS — so an attacker could create admin@victim.com under their own
260	  // subscription, call resetMailboxPassword() (which passes its ownership check
261	  // because the row is theirs), and have the password of the victim's real, live
262	  // mailbox handed back to them. Cost of the attack: the cheapest email plan.
263	  const dupe = await db.emailSubscription.findFirst({
264	    where: { domainName: name, status: { not: "CANCELLED" } },
265	  });
266	  if (dupe) {
267	    return {
268	      error:
269	        dupe.userId === user.id
270	          ? "This domain already has an email subscription."
271	          : "That domain is already set up for email on Nxeon. If it belongs to you, contact support and we'll verify ownership and move it across.",
272	    };
273	  }
274	
275	  // Seasonal promo = HONEST intro discount on the FIRST term only. The renewal
276	  // path (worker/product-renewals.ts) bills plan.priceCents unchanged, so the
277	  // strikethrough shown on the pricing page is the real renewal price and this
278	  // discounted value is the real first-term price — displayed === charged.
279	  const promo = currentPromo(new Date());
280	  const chargeCents = promoPriceCents(plan.priceCents, promo);
281	  const promoNote = promo.discountPercent > 0 ? ` — ${promo.name} ${promo.discountPercent}% off first term` : "";
282	  if (user.balanceCents < chargeCents) {
283	    return { error: "Insufficient balance. Top up your wallet first." };
284	  }
285	
286	  try {
287	    await db.$transaction(async (tx) => {
288	      await debitWallet(tx, user.id, chargeCents);
289	      await tx.walletTransaction.create({
290	        data: {
291	          userId: user.id,
292	          amountCents: -chargeCents,
293	          description: `Business Email: ${plan.name} for ${name}${promoNote}`,
294	        },
295	      });
296	      await tx.emailSubscription.create({
297	        data: {
298	          userId: user.id,
299	          domainName: name,
300	          emailPlanId: plan.id,
301	          status: "ACTIVE",
302	          autoRenew: true,
303	          expiresAt: addMonths(new Date(), plan.termMonths),
304	          // In-account domains: we control DNS, so treat as verified now. External
305	          // domains: not verified until the customer publishes DNS + we confirm it.
306	          external,
307	          verified: !external,
308	          verifiedAt: external ? null : new Date(),
309	          verifyToken: external ? randomBytes(24).toString("hex") : null,
310	        },
311	      });
312	    });
313	  } catch (e) {
314	    if (e instanceof InsufficientBalanceError) {
315	      return { error: "Insufficient balance. Top up your wallet first." };
316	    }
317	    throw e;
318	  }
319	
320	  await db.auditLog.create({
321	    data: {
322	      userId: user.id,
323	      action: "emailhosting.order",
324	      detail: `${name} plan=${plan.name}${external ? " (external — DNS verification required)" : ""}`,
325	    },
326	  });
327	  revalidatePath("/dashboard/email");
328	  return { ok: true };
329	}
