333	/**
334	 * Return the DNS records a customer must publish at their registrar for an
335	 * EXTERNAL domain so mail flows through the Nxeon mail server, plus the
336	 * ownership-verification record. Ownership-checked (caller must own the sub).
337	 *
338	 * The DKIM record is fetched from Mailcow (`mcGetDkim`) and cached in
339	 * `dkimRecord`; when Mailcow isn't configured (or has no key yet) a placeholder
340	 * note is returned so the panel still renders.
341	 */
342	export async function getEmailDnsRecords(
343	  subscriptionId: string,
344	): Promise<{
345	  error?: string;
346	  records?: DnsRecord[];
347	  verified?: boolean;
348	  external?: boolean;
349	  cloudflareConnected?: boolean;
350	}> {
351	  const user = await requireUser();
352	
353	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
354	  if (!sub) return { error: "Subscription not found." };
355	  if (sub.userId !== user.id) return { error: "Not your subscription." };
356	
357	  const domain = sub.domainName;
358	
359	  // Resolve the DKIM TXT: prefer the cached value, else fetch + cache from Mailcow.
360	  let dkimTxt = sub.dkimRecord ?? null;
361	  if (!dkimTxt && mailcowConfigured()) {
362	    try {
363	      // Ensure the mail domain exists so Mailcow has generated a DKIM key.
364	      if (!(await mcDomainExists(domain))) {
365	        await mcCreateDomain(domain).catch(() => {});
366	      }
367	      dkimTxt = await mcGetDkim(domain);
368	      if (dkimTxt) {
369	        await db.emailSubscription
370	          .update({ where: { id: sub.id }, data: { dkimRecord: dkimTxt } })
371	          .catch(() => {});
372	      }
373	    } catch (e) {
374	      console.warn(`[mailcow] get dkim ${domain} failed:`, e);
375	    }
376	  }
377	
378	  const records: DnsRecord[] = [
379	    {
380	      type: "TXT",
381	      label: "Ownership verification",
382	      host: `_nxeon-verify.${domain}`,
383	      value: `nxeon-verify=${sub.verifyToken ?? ""}`,
384	      note: "Proves you control this domain. Required before mail is enabled.",
385	    },
386	    {
387	      type: "MX",
388	      label: "Mail routing (MX)",
389	      host: domain,
390	      value: MAIL_HOST,
391	      priority: MAIL_MX_PRIORITY,
392	    },
393	    {
394	      type: "TXT",
395	      label: "SPF",
396	      host: domain,
397	      value: SPF_VALUE,
398	      note: "Authorizes the Nxeon mail server to send for your domain.",
399	    },
400	    {
401	      type: "TXT",
402	      label: "DKIM",
403	      host: `${DKIM_SELECTOR}._domainkey.${domain}`,
404	      value: dkimTxt ?? "",
405	      note: dkimTxt
406	        ? undefined
407	        : "DKIM key is being generated on the mail server — refresh this page shortly to see the value.",
408	    },
409	    {
410	      type: "TXT",
411	      label: "DMARC",
412	      host: `_dmarc.${domain}`,
413	      value: DMARC_VALUE,
414	      note: "Reporting policy for messages that fail SPF/DKIM.",
415	    },
416	  ];
417	
418	  return {
419	    records,
420	    verified: sub.verified,
421	    external: sub.external,
422	    // True for either connection shape (OAuth credentials or a legacy token).
423	    cloudflareConnected: readStoredCloudflare(user.cloudflareTokenEnc) !== null,
424	  };
425	}
