427	/**
428	 * Verify that an EXTERNAL domain's owner has published our verification record.
429	 * Resolves the `_nxeon-verify` TXT via DNS and confirms it contains
430	 * `nxeon-verify=<verifyToken>`; the MX pointing at the mail host is accepted as
431	 * corroboration. The result is derived entirely server-side from live DNS —
432	 * client input never decides the outcome. Rate-limited per user + subscription.
433	 */
434	export async function verifyEmailDomain(subscriptionId: string): Promise<Result> {
435	  const user = await requireUser();
436	
437	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
438	  if (!sub) return { error: "Subscription not found." };
439	  if (sub.userId !== user.id) return { error: "Not your subscription." };
440	  if (!sub.external) return { error: "This domain is managed by Nxeon — no verification needed." };
441	  if (sub.verified) return { ok: true };
442	  if (!sub.verifyToken) return { error: "No verification token on this subscription." };
443	
444	  const rl = checkRateLimit(`email-verify:${user.id}:${sub.id}`, {
445	    max: 6,
446	    windowMs: 60_000,
447	  });
448	  if (!rl.ok) {
449	    return { error: `Too many verification attempts. Try again in ${rl.retryAfterSec}s.` };
450	  }
451	
452	  const domain = sub.domainName;
453	  const expected = `nxeon-verify=${sub.verifyToken}`;
454	
455	  // Primary signal: the verification TXT record must contain our exact token.
456	  let tokenFound = false;
457	  try {
458	    const txt = await resolveTxt(`_nxeon-verify.${domain}`);
459	    // Each record may be split into multiple strings — join per-record chunks.
460	    tokenFound = txt.some((chunks) => chunks.join("").trim() === expected);
461	  } catch {
462	    tokenFound = false;
463	  }
464	
465	  // Corroboration: MX pointing at the mail host (does not substitute for the token).
466	  let mxOk = false;
467	  try {
468	    const mx = await resolveMx(domain);
469	    mxOk = mx.some((r) => r.exchange.replace(/\.$/, "").toLowerCase() === MAIL_HOST);
470	  } catch {
471	    mxOk = false;
472	  }
473	
474	  if (!tokenFound) {
475	    return {
476	      error: mxOk
477	        ? "MX is set, but the _nxeon-verify TXT record isn't visible yet. DNS can take a few minutes to propagate."
478	        : "Verification record not found yet. Add the _nxeon-verify TXT record and try again (DNS can take a few minutes).",
479	    };
480	  }
481	
482	  await db.emailSubscription.update({
483	    where: { id: sub.id },
484	    data: { verified: true, verifiedAt: new Date() },
485	  });
486	
487	  await db.auditLog.create({
488	    data: {
489	      userId: user.id,
490	      action: "emailhosting.verify",
491	      detail: `${domain}${mxOk ? " (MX + TXT)" : " (TXT)"}`,
492	    },
493	  });
494	  revalidatePath("/dashboard/email");
495	  return { ok: true };
496	}
