498	// Local-part of an email address: RFC-ish, conservative. No leading/trailing dot.
499	const localPartRe = /^[a-z0-9]+(?:[._-][a-z0-9]+)*$/;
500	
501	/**
502	 * Add a mailbox to a subscription the caller owns. Enforces the plan's mailbox
503	 * quota and address uniqueness within the subscription, records the intended
504	 * mailbox (status PROVISIONING), then attempts to provision it on Mailcow. A
505	 * Mailcow failure leaves the row as FAILED (retryable) but never fails the call.
506	 */
507	export async function addMailbox(subscriptionId: string, localPart: string): Promise<Result> {
508	  const user = await requireUser();
509	
510	  const sub = await db.emailSubscription.findUnique({
511	    where: { id: subscriptionId },
512	    include: { emailPlan: true, mailboxes: true },
513	  });
514	  if (!sub) return { error: "Subscription not found." };
515	  if (sub.userId !== user.id) return { error: "Not your subscription." };
516	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
517	  // SECURITY (added 2026-07-25): defence in depth against the cross-tenant
518	  // takeover fixed in subscribeEmail(). Owning the subscription ROW is not proof
519	  // of owning the DOMAIN — and because Mailcow keys mailboxes by address, any
520	  // mailbox minted here acts on that domain's real mail. An external domain must
521	  // prove control via DNS before it can mint a single address, so even if a
522	  // duplicate subscription is ever created again this cannot be weaponised.
523	  if (sub.external && !sub.verified) {
524	    return {
525	      error: "Verify this domain first — add the DNS record shown on this page, then click Verify.",
526	    };
527	  }
528	
529	  const local = String(localPart ?? "").trim().toLowerCase();
530	  if (!localPartRe.test(local) || local.length > 64) {
531	    return { error: "Enter a valid mailbox name (letters, numbers, . _ - )." };
532	  }
533	
534	  const address = `${local}@${sub.domainName}`;
535	
536	  if (sub.mailboxes.length >= sub.emailPlan.mailboxes) {
537	    return {
538	      error: `Plan limit reached (${sub.emailPlan.mailboxes} mailbox${sub.emailPlan.mailboxes === 1 ? "" : "es"}). Upgrade to add more.`,
539	    };
540	  }
541	  if (sub.mailboxes.some((m) => m.address.toLowerCase() === address)) {
542	    return { error: "That address already exists." };
543	  }
544	
545	  // Per-mailbox quota (MB) comes from the plan tier's per-mailbox storage (GB).
546	  const quotaMB = sub.emailPlan.storageGB * 1024;
547	
548	  const mailbox = await db.mailbox.create({
549	    data: { subscriptionId: sub.id, address, quotaMB, status: "PROVISIONING" },
550	  });
551	
552	  await db.auditLog.create({
553	    data: { userId: user.id, action: "mailbox.add", detail: address },
554	  });
555	
556	  // Additive, failure-tolerant provisioning — never throws out of the flow.
557	  await provisionMailboxOnMailcow({
558	    id: mailbox.id,
559	    address: mailbox.address,
560	    quotaMB,
561	    subscription: { domainName: sub.domainName },
562	  });
563	
564	  revalidatePath("/dashboard/email");
565	  return { ok: true };
566	}
