753	/**
754	 * Store a customer's Cloudflare API token (encrypted) so we can create their
755	 * mail DNS records for them. The token is verified against Cloudflare before it
756	 * is saved, so we never persist a dud. requireUser + rate-limited; the token is
757	 * never logged or returned. Scope guidance (Zone → DNS → Edit) lives in the UI.
758	 */
759	export async function saveCloudflareToken(token: string): Promise<Result> {
760	  const user = await requireUser();
761	
762	  const t = String(token ?? "").trim();
763	  if (!t) return { error: "Paste your Cloudflare API token." };
764	  if (t.length < 20 || t.length > 200) {
765	    return { error: "That doesn't look like a Cloudflare API token." };
766	  }
767	
768	  const rl = checkRateLimit(`cf-token:${user.id}`, { max: 6, windowMs: 60_000 });
769	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
770	
771	  let valid = false;
772	  try {
773	    valid = await cfVerifyToken(t);
774	  } catch (e) {
775	    console.warn("[cloudflare] token verify failed:", e);
776	    return { error: "Couldn't reach Cloudflare to verify the token. Try again shortly." };
777	  }
778	  if (!valid) {
779	    return {
780	      error: "Cloudflare rejected that token. Check it's active and scoped to Zone → DNS → Edit.",
781	    };
782	  }
783	
784	  await db.user.update({
785	    where: { id: user.id },
786	    data: { cloudflareTokenEnc: encryptSecret(t) },
787	  });
788	  await db.auditLog.create({
789	    data: { userId: user.id, action: "cloudflare.connect", detail: "API token saved" },
790	  });
791	  revalidatePath("/dashboard/email");
792	  return { ok: true };
793	}
794	
795	/**
796	 * Auto-create the mail DNS records for an EXTERNAL email subscription in the
797	 * customer's Cloudflare zone, using their stored token. Ownership-checked and
798	 * rate-limited. Reuses getEmailDnsRecords as the single source of truth for the
799	 * record set (ownership verify TXT, MX, SPF, DKIM, DMARC), upserts each into the
800	 * zone, then leaves the existing verifyEmailDomain flow to confirm. Fails
801	 * gracefully with clear messages for invalid token / zone-not-found.
802	 */
803	export async function autoCreateEmailDns(
804	  subscriptionId: string,
805	): Promise<{ error?: string; ok?: boolean; created?: string[] }> {
806	  const user = await requireUser();
807	
808	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
809	  if (!sub) return { error: "Subscription not found." };
810	  if (sub.userId !== user.id) return { error: "Not your subscription." };
811	  if (!sub.external) {
812	    return { error: "This domain is managed by Nxeon — no external DNS setup is needed." };
813	  }
814	
815	  const rl = checkRateLimit(`cf-autodns:${user.id}:${sub.id}`, { max: 4, windowMs: 60_000 });
816	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
817	
818	  // Works for both connection shapes: OAuth credentials (refreshed here when
819	  // stale) and a legacy pasted API token. Never handles the plaintext itself.
820	  const resolved = await resolveCloudflareToken(user);
821	  const token = resolved.token;
822	  if (!token) return { error: resolved.error ?? "Connect Cloudflare first." };
823	
824	  // Same record set the customer would otherwise publish by hand.
825	  const dns = await getEmailDnsRecords(subscriptionId);
826	  if (dns.error) return { error: dns.error };
827	  const records = (dns.records ?? []).filter((r) => r.type === "MX" || r.value.trim());
828	  if (records.length === 0) {
829	    return { error: "No DNS records to create yet — try again in a moment." };
830	  }
831	
832	  // SANDBOX: never contact Cloudflare — report what we would have published so
833	  // staging can walk the whole "connect → records added" flow.
834	  if (SANDBOX) {
835	    return {
836	      ok: true,
837	      created: records.map((r) => `${r.label} (${r.type}, created)`),
838	    };
839	  }
840	
841	  let zoneId: string | null;
842	  try {
843	    zoneId = await cfFindZoneId(token, sub.domainName);
844	  } catch (e) {
845	    if (e instanceof CloudflareError) {
846	      return { error: `Cloudflare error: ${e.message}` };
847	    }
848	    throw e;
849	  }
850	  if (!zoneId) {
851	    return {
852	      error: `No Cloudflare zone found for ${sub.domainName}. Add the domain to Cloudflare first, or check the token is scoped to this zone.`,
853	    };
854	  }
855	
856	  let created: string[];
857	  try {
858	    const results = await cfUpsertRecords(
859	      token,
860	      zoneId,
861	      records.map((r) => ({
862	        type: r.type,
863	        name: r.host,
864	        content: r.value,
865	        priority: r.priority,
866	      })),
867	    );
868	    created = results.map((res) => {
869	      const label = records.find((r) => r.host === res.name && r.type === res.type)?.label ?? res.name;
870	      return `${label} (${res.type}, ${res.action})`;
871	    });
872	  } catch (e) {
873	    if (e instanceof CloudflareError) {
874	      return {
875	        error: `Couldn't create records in Cloudflare: ${e.message}. Check the token has Zone → DNS → Edit permission.`,
876	      };
877	    }
878	    throw e;
879	  }
880	
881	  await db.auditLog.create({
882	    data: {
883	      userId: user.id,
884	      action: "cloudflare.autodns",
885	      detail: `${sub.domainName} — ${created.length} record(s)`,
886	    },
887	  });
888	  revalidatePath("/dashboard/email");
889	  return { ok: true, created };
890	}
