39	export function EmailHosting({
40	  domains,
41	  plans,
42	  subscriptions,
43	  balanceCents,
44	}: {
45	  domains: string[];
46	  plans: PlanOpt[];
47	  subscriptions: SubscriptionRow[];
48	  balanceCents: number;
49	}) {
50	  // Registered domains without a subscription are offered as quick suggestions,
