67	      <section>
68	        <h2 className="mb-3 text-lg font-semibold text-white">Your email subscriptions</h2>
69	        {subscriptions.length === 0 ? (
70	          <div className="card text-sm text-slate-400">
71	            No email subscriptions yet. Pick a domain and a plan above to get started.
