108	        </span>
109	      </div>
110	    </div>
111	  );
112	}
113	
114	function OrderPanel({
115	  suggestedDomains,
116	  plans,
117	  balanceCents,
118	}: {
119	  suggestedDomains: string[];
120	  plans: PlanOpt[];
121	  balanceCents: number;
122	}) {
123	  const [domain, setDomain] = useState(suggestedDomains[0] ?? "");
