133	
134	  function submit() {
135	    if (!domain.trim()) {
136	      setError("Enter a domain.");
137	      return;
138	    }
139	    setError(null);
140	    setOk(false);
141	    start(async () => {
142	      const res = await orderEmailHosting(domain.trim(), planId);
143	      if (res?.error) setError(res.error);
144	      else if (res?.ok) setOk(true);
145	    });
146	  }
147	
148	  return (
149	    <section>
150	      <h2 className="mb-3 text-lg font-semibold text-white">Add email hosting</h2>
151	      <div className="card space-y-4">
152	        {error && (
153	          <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
