180	            </datalist>
181	            <p className="mt-1 text-xs text-slate-500">
182	              {isExternal
183	                ? "Registered elsewhere — you'll add DNS records and verify after ordering."
184	                : "In your account — DNS is configured for you."}
185	            </p>
186	          </div>
187	          <div>
188	            <label className="label">Plan</label>
189	            <select className="input" value={planId} onChange={(e) => setPlanId(e.target.value)}>
190	              {plans.map((p) => (
191	                <option key={p.id} value={p.id}>
192	                  {p.name} — {p.mailboxes} mailbox{p.mailboxes === 1 ? "" : "es"} · {p.storageGB}GB ·{" "}
193	                  {fmtMoney(p.priceCents)}
194	                  {p.termMonths > 1 ? `/${p.termMonths}mo` : "/mo"}
