203	            <span className="text-slate-300">
204	              {selected.mailboxes} mailbox{selected.mailboxes === 1 ? "" : "es"} · {selected.storageGB} GB each
205	            </span>
206	            <span className="text-white">
207	              {fmtMoney(selected.priceCents)}
208	              {selected.termMonths > 1 ? ` / ${selected.termMonths} mo` : " / mo"}
209	            </span>
210	          </div>
211	        )}
212	
213	        <div className="flex flex-wrap items-center justify-between gap-3">
214	          <span className="text-xs text-slate-500">
215	            Wallet balance: <span className="text-slate-300">{fmtMoney(balanceCents)}</span>
216	          </span>
