218	            {pending ? "Ordering…" : "Order email hosting"}
219	          </button>
220	        </div>
221	      </div>
222	    </section>
223	  );
224	}
225	
226	function SubscriptionCard({ sub }: { sub: SubscriptionRow }) {
227	  const atLimit = sub.mailboxes.length >= sub.planMailboxes;
